let C,S,Q=[],done=null;
function fresh(i){return{i,act:0,step:0,notes:[],evidence:[],choices:[],strategy:null,ending:null,savedAt:null}}
function key(i){return'av-five-'+i}
function save(){S.savedAt=Date.now();localStorage.setItem(key(S.i),JSON.stringify(S))}
function load(i){try{return JSON.parse(localStorage.getItem(key(i)))||fresh(i)}catch(e){return fresh(i)}}
function shell(){document.getElementById('imGame')?.remove();const e=document.createElement('section');e.id='imGame';e.className='v3 av';e.innerHTML=`<div class="v-bg avbg i${S.i}"></div><header class="v-top"><div><small id="vAct"></small><b>${C.title}</b></div><div><button onclick="avNotes()">法脉札记 <em id="vNoteCount"></em></button><button onclick="avExit()">返回八案</button></div></header><aside class="v-goal"><b>当前目标</b><span id="vGoal"></span><div class="v-progress">${[0,1,2,3,4].map(i=>`<i id="vP${i}"></i>`).join('')}</div></aside><div class="v-ye avchar i${S.i}"></div><main id="vStage"></main><div id="vDialog" class="v-dialog hidden" onclick="avAdvance()"><strong id="vSpeaker"></strong><p id="vText"></p><span id="vNext">点击继续 ▾</span><div id="vChoices"></div></div><div id="vModal" class="v-modal hidden"></div></section>`;document.body.appendChild(e)}
const actNames=['时代入局','案情发现','证据对质','制度抉择','最终裁断'];
function start(i){C=V[i];S=load(i);shell();if(S.savedAt&&(S.act||S.evidence.length||S.ending))modal(`<h1>继续第${'一二三四五'[S.act]}幕？</h1><p>已解锁 ${S.notes.length}/6 条法脉札记。</p><button class="primary" onclick="avRun()">继续存卷</button><button onclick="avRestart()">重新开始</button>`);else run()}
function run(){close();paint();if(S.ending)return ending();if(S.act===0)return intro();if(S.act===1)return investigate();if(S.act===2)return confront();if(S.act===3)return crisis();court()}
function paint(){document.getElementById('vAct').textContent=`第${'二三四五六七八'[S.i-1]}卷 · ${C.era} · ${actNames[S.act]}`;document.getElementById('vGoal').textContent=[`理解${C.theme}`,`依次核验三件关键材料`,`让证据进入人物对质`,`承担制度选择的人物后果`,`在正式裁断中运用本卷知识`][S.act];document.getElementById('vNoteCount').textContent=S.notes.length;[0,1,2,3,4].forEach(i=>document.getElementById('vP'+i).className=i<S.act?'done':i===S.act?'now':'')}
function intro(){stage(`<div class="v-center"><div class="v-seal">${'二三四五六七八'[S.i-1]}</div><h1>${C.title}</h1><p>${C.intro.join('<br>')}</p><button class="primary" onclick="avIntroTalk()">进入时代</button></div>`)}
function introTalk(){dialogue([['旁白',C.intro[0]],[C.role,C.intro[1]],[C.conflict[0],C.conflict[1]],[C.conflict[2],C.conflict[3]],[C.role,'你决定先以何种立场进入案件？',C.crisis.map(x=>[x[0],x[1],x[2]])]],()=>unlock([0,1],finish))}
function investigate(){stage(`<div class="v-three">${C.evidence.map((x,i)=>`<button ${i>S.evidence.length?'disabled':''} onclick="avEvidence(${i})"><b>${i+1} · ${x[0]}</b><span>${i<S.evidence.length?'已收入案卷':'点击核验'}</span></button>`).join('')}</div><div class="v-task">按顺序核验材料。每件证据只回答一个事实问题，不会自动证明全案。</div>`)}
function evidence(i){if(i>S.evidence.length)return;if(!S.evidence.includes(i))S.evidence.push(i);save();modal(`<small>证据收集</small><h2>${C.evidence[i][0]}</h2><p>${C.evidence[i][1]}</p><p><b>证据边界：</b>该材料需要与其他事实互证，不能单独替代完整裁断。</p><button class="primary" onclick="avContinueEvidence()">收入案卷</button>`)}
function continueEvidence(){close();if(S.evidence.length===3)unlock([2,3],finish);else run()}
function confront(){stage(`<div class="v-center"><h1>人物对质</h1><p>三件材料已经形成证据链。现在让两种制度立场直接交锋。</p><button class="primary" onclick="avConfrontTalk()">开始对质</button></div>`)}
function confrontTalk(){dialogue([[C.role,`“${C.evidence[0][0]}”说明${C.evidence[0][1]}；其余材料又补足了事实链。`],[C.conflict[0],C.conflict[1]],[C.conflict[2],C.conflict[3]],[C.role,'你不能只判断谁在说谎，还要决定当时制度如何处理这种冲突。']],finish)}
function crisis(){stage(`<div class="v-center"><h1>制度抉择</h1><p>调查已经结束。现在只处理人物和制度后果，不再增加新证据。</p><div class="v-decisions">${C.crisis.map(x=>`<button onclick="avStrategy('${x[1]}')">${x[0]}<small>${x[2]}</small></button>`).join('')}</div></div>`)}
function strategy(x){S.strategy=x;save();unlock([4],finish)}
function court(){stage(`<div class="v-court"><h1>${S.i===7?'修律馆表决':'正式裁断'}</h1><p>三轮回应将决定本卷结局。前四幕的证据和札记在此转化为可用理由。</p><button class="primary" onclick="avCourtTalk()">开始</button></div>`)}
function courtTalk(){const lines=[];C.court.forEach((q,n)=>{lines.push([n===2?'主审者':C.conflict[0],q[0]]);lines.push([C.role,'你的回应是——',q[1].map(x=>[x[0],x[1],x[0]])])});dialogue(lines,()=>unlock([5],resolve))}
function resolve(){const good=['bounded','reform','separate','review','documents','balance'];let id='weak';if(S.choices.some(x=>['all','same','confession','real','clan','ritual'].includes(x))||['all','same','old','clan','real','ritual'].includes(S.strategy))id='hard';if(S.choices.filter(x=>['trust','verify','rule','purpose','graded','feedback','scope','limited','separate','autopsy','review','chain','documents','verify','review','family','delay','modern','balance','sovereignty'].includes(x)).length>=2||good.includes(S.strategy))id='good';S.ending=id;save();ending()}
function ending(){const d=C.endings[S.ending]||C.endings.weak;stage(`<div class="v-end"><small>第${'二三四五六七八'[S.i-1]}卷结局</small><h1>${d[0]}</h1><p>${d[1]}</p><div class="v-graph"><b>本卷知识图谱</b>${S.notes.map(i=>`<span>${C.notes[i][0]}</span>`).join('')}<p>时代背景 → 人物冲突 → 证据调查 → 制度适用 → 历史后果</p></div><button class="primary" onclick="avNotes()">查看完整札记</button><button onclick="avComplete()">归档并返回八案</button></div>`)}
function finish(){modal(`<small>本幕完成</small><h1>${actNames[S.act]}</h1><p>${['你已经理解本卷时代矛盾。','事实材料已进入案卷。','人物立场已被证据检验。','你已承担制度选择的后果。','裁断完成。'][S.act]}</p><button class="primary" onclick="avNext()">进入下一幕</button>`)}
function next(){close();S.act++;save();run()}
function unlock(ids,cb){ids.forEach(i=>{if(!S.notes.includes(i))S.notes.push(i)});save();modal(`<small>法脉札记收集</small>${ids.map(i=>`<h2>${C.notes[i][0]}</h2><p>${C.notes[i][1]}</p>`).join('')}<button class="primary" id="avU">继续剧情</button>`);document.getElementById('avU').onclick=()=>{close();cb()}}
function notes(){modal(`<h1>${C.title} · 法脉札记</h1>${C.notes.map((n,i)=>`<article class="${S.notes.includes(i)?'':'locked'}"><h2>${S.notes.includes(i)?n[0]:'尚未解锁'}</h2><p>${S.notes.includes(i)?n[1]:'继续推进对应剧情。'}</p></article>`).join('')}<button onclick="avClose()">合卷</button>`)}
function dialogue(lines,cb){Q=lines.slice();done=cb;nextLine()}function nextLine(){if(!Q.length){hide();const f=done;done=null;if(f)f();return}const l=Q.shift(),d=document.getElementById('vDialog');d.classList.remove('hidden');document.getElementById('vSpeaker').textContent=l[0];document.getElementById('vText').textContent=l[1];const b=document.getElementById('vChoices');b.innerHTML='';document.getElementById('vNext').hidden=!!l[2];if(l[2])l[2].forEach((x,i)=>{const y=document.createElement('button');y.innerHTML=`<b>${String.fromCharCode(65+i)}</b>${x[0]}<small>${x[2]}</small>`;y.onclick=e=>{e.stopPropagation();S.choices.push(x[1]);save();nextLine()};b.appendChild(y)})}
function advance(){if(document.getElementById('vChoices').children.length)return;nextLine()}function hide(){document.getElementById('vDialog').classList.add('hidden')}function stage(h){document.getElementById('vStage').innerHTML=h}function modal(h){const m=document.getElementById('vModal');m.classList.remove('hidden');m.innerHTML=`<div>${h}</div>`}function close(){document.getElementById('vModal').classList.add('hidden')}
function complete(){window.unlockVolume&&window.unlockVolume(S.i,C.endings[S.ending][0],S.choices);exit()}
function exit(){save();document.getElementById('imGame')?.remove();window.openMap()}
