investigate=function(){stage(`<section class="av-workbench"><header><div><small>${C.era} · 案例模拟</small><h1>${C.title}</h1><p>${C.intro[1]}</p></div><b>证据 ${S.evidence.length}/4</b></header><div class="av-columns"><aside><h3>涉案立场</h3><article><b>${C.conflict[0]}</b><span>${C.conflict[1]}</span></article><article><b>${C.conflict[2]}</b><span>${C.conflict[3]}</span></article></aside><main><h3>证据材料 <small>按顺序研判证明力</small></h3><div class="av-evidence-grid">${C.evidence.map((x,i)=>`<button ${i>S.evidence.length?'disabled':''} class="${i<S.evidence.length?'found':''}" onclick="avEvidence(${i})"><i>${i+1}</i><b>${x[0]}</b><span>${i<S.evidence.length?'已研判 · 可复核':i===S.evidence.length?'点击研判':'前件未完成'}</span></button>`).join('')}</div><div class="av-tip"><b>本卷制度焦点</b><p>${C.theme}</p></div></main><aside><h3>法脉札记</h3>${C.notes.slice(0,3).map((n,i)=>`<article class="${S.notes.includes(i)?'on':''}"><b>${S.notes.includes(i)?n[0]:'尚未解锁'}</b><span>${S.notes.includes(i)?n[1]:'推进剧情后显示'}</span></article>`).join('')}</aside></div></section>`)};
evidence=function(i){if(i>S.evidence.length)return;const e=C.evidence[i];modal(`<small>第 ${i+1}/4 件物证 · 先判断后收入</small><h1>${e[0]}</h1><p>${e[1]}</p><h2>这件材料应当怎样使用？</h2><div class="av-proof"><button onclick="avJudge(${i},'chain')">限定其证明对象，并与其他材料互证</button><button onclick="avJudge(${i},'absolute')">凭这一件材料直接认定全案</button><button onclick="avJudge(${i},'discard')">材料不能单独定案，所以完全排除</button></div><button onclick="avClose()">暂不收入</button>`)};
