courtTalk=function(){const lines=[];C.court.forEach((q,n)=>{lines.push([n===C.court.length-1?'主审者':C.conflict[n%2===0?0:2],q[0]]);lines.push([C.role,'你的回应是——',q[1].map(x=>[x[0],x[1],`第${n+1}轮 · 选择将影响最终结局`])])});dialogue(lines,()=>unlock([4,5],resolve))};
start=function(i){C=V[i];S=load(i);S.visited=S.visited||[];shell();if(S.savedAt&&(S.act||S.evidence.length||S.ending||S.visited.length))modal(`<small>发现分卷存档</small><h1>继续《${C.title}》？</h1><p>已完成场景 ${S.visited.length}/2 · 物证 ${S.evidence.length}/4 · 法脉札记 ${S.notes.length}/6</p><button class="primary" onclick="avRun()">继续存卷</button><button onclick="avRestart()">重新开始</button>`);else run()};
run=function(){close();paint();if(S.ending)return ending();if(S.act===0)return intro();if(S.act===1)return routeMap();if(S.act===2)return confront();if(S.act===3)return crisis();court()};
intro=function(){stage(`<section class="d-platform av-guide"><nav class="d-side"><h2>律令山河录</h2><button class="on">时代导学</button><button>人物会面</button><button>案卷调查</button><button>模拟法庭</button><button onclick="avNotes()">法脉札记</button></nav><div class="d-platform-main"><header><small>第${'二三四五六七八'[S.i-1]}卷 · ${C.era}</small><h1>${C.title}</h1></header><section class="d-overview"><div><small>你的身份 · ${C.role}</small><h2>${C.theme}</h2><p>${C.intro.join('')}</p></div><aside><b>本卷学习目标</b>${C.notes.slice(0,3).map(n=>`<span>${n[0]}</span>`).join('')}</aside></section><div class="d-module-grid"><article><i>史</i><b>时代背景</b><span>${C.intro[0]}</span></article><article><i>人</i><b>核心人物</b><span>${C.conflict[0]} · ${C.conflict[2]}</span></article><article><i>案</i><b>制度争点</b><span>${C.theme}</span></article><article><i>证</i><b>四件物证</b><span>${C.evidence.map(x=>x[0]).join('、')}</span></article><article><i>审</i><b>五轮审理</b><span>事实、规则、程序与制度后果</span></article><article><i>结</i><b>分支结局</b><span>选择形成判词，不设置分数等级</span></article></div><footer class="d-enter"><p>本卷采用“人物立场—证据研判—制度适用—历史后果”的完整互动结构。</p><button class="primary" onclick="avIntroTalk()">以${C.role}身份入卷</button></footer></div></section>`)};
function routeMap(){const metA=S.visited.includes('a'),metB=S.visited.includes('b'),ready=metA&&metB;stage(`<section class="d-map av-route-map"><div class="d-map-title"><small>${C.era} · 案卷行旅图</small><h1>${C.title}</h1><p>先完成两场人物会面，再进入案卷现场研判四件物证。</p></div><div class="d-route"></div><button class="d-place ${metA?'done':''}" style="left:18%;top:62%" onclick="avVisit('a')"><i>1</i><b>${C.conflict[0]}</b><span>听取制度主张</span></button><button class="d-place ${metB?'done':''}" style="left:45%;top:28%" onclick="avVisit('b')"><i>2</i><b>${C.conflict[2]}</b><span>听取相反立场</span></button><button class="d-place ${ready?'':'locked'}" style="left:73%;top:58%" onclick="avVisit('e')"><i>3</i><b>案卷调查处</b><span>${ready?'研判四件物证':'先完成人物会面'}</span></button><button class="d-place locked" style="left:48%;top:80%"><i>4</i><b>${S.i===7?'修律馆':'正式审理堂'}</b><span>收集证据后开放</span></button><aside class="d-map-log"><b>本卷进度</b><span>人物会面 ${S.visited.length}/2</span><span>物证 ${S.evidence.length}/4</span><span>知识节点 ${S.notes.length}/6</span></aside></section>`)};
window.avVisit=id=>{if(id==='e'){if(!(S.visited.includes('a')&&S.visited.includes('b')))return modal('<h1>前序未完成</h1><p>请先听取两方人物的完整主张。</p><button onclick="avClose()">返回地图</button>');return investigate()}const first=id==='a',person=first?C.conflict[0]:C.conflict[2],claim=first?C.conflict[1]:C.conflict[3];dialogue([[person,claim],[C.role,`你主张的依据是什么？若与物证冲突，是否愿意接受复核？`],[person,first?'制度若失去威信，执行便会动摇；但我愿看你拿出的材料。':'我并非请求法外开恩，只要求把身份、行为与证据分别判断。'],[C.role,'你如何记录这次会面？',[[`记录其制度理由，同时保留证据复核`,'meet_reason','知识节点：人物立场不能替代证据'],[`因其身份较高，直接采纳全部主张`,'meet_status','知识节点：身份不能自动决定事实'],[`只按个人好恶评价，不记录制度依据`,'meet_moral','知识节点：历史评价需要时代语境']]],[person,'我会在正式审理中等待你的回应。']],()=>{if(!S.visited.includes(id))S.visited.push(id);save();routeMap()})};
ending=function(){const d=C.endings[S.ending]||C.endings.weak;stage(`<section class="d-ending av-ending"><div class="d-end-scroll"><small>第${'二三四五六七八'[S.i-1]}卷剧情结局</small><h1>${d[0]}</h1><p class="lead">${d[1]}</p><div class="d-tabs"><button class="on" onclick="avEndTab(this,'learn')">我学会了什么</button><button onclick="avEndTab(this,'route')">我的选择轨迹</button><button onclick="avEndTab(this,'boundary')">史实边界</button></div><div id="avEndPanel"></div><div class="d-end-actions"><button class="primary" onclick="avComplete()">归档并返回八案</button><button onclick="avRestart()">重开本卷</button><button onclick="avNotes()">查看法脉札记</button></div></div></section>`);window.avEndTab(document.querySelector('.d-tabs button'),'learn')};
window.avEndTab=(btn,type)=>{document.querySelectorAll('.d-tabs button').forEach(x=>x.classList.remove('on'));btn.classList.add('on');const p=document.getElementById('avEndPanel');if(type==='learn')p.innerHTML=`<h2>本卷知识总结</h2><div class="d-know-grid">${C.notes.map(n=>`<article><b>${n[0]}</b><span>${n[1]}</span></article>`).join('')}</div>`;if(type==='route')p.innerHTML=`<h2>选择轨迹</h2><p>人物会面 ${S.visited.length}/2 · 物证研判 ${S.evidence.length}/4 · 正式审理 ${C.court.length}轮</p><ol>${S.choices.map(x=>`<li>${x}</li>`).join('')}</ol>`;if(type==='boundary')p.innerHTML=`<h2>史实与教学化虚构</h2><p>${C.notes.map(n=>n[0]).join('、')}属于本卷法制史知识范围；具体人物对话、证据组合和审理程序为教学化虚构，用于帮助理解${C.theme}。</p>`};
dialogue=function(lines,cb){stage(`<section class="av-character-scene i${S.i}"><div class="av-scene-label"><small>${C.era} · ${actNames[S.act]}</small><h1>${C.title}</h1><p>${S.act===0?'人物将带你进入真实的制度争论。':S.act===2?'让物证检验双方人物的主张。':S.act===4?'正式审理中的每次回应都会改变结局。':'听取人物立场并记录其制度依据。'}</p></div><div class="av-person left p${S.i%4}"></div><div class="av-person right p${(S.i+2)%4}"></div><div class="av-scene-place">${S.act===0?'时代入局':S.act===2?'人物对质':S.act===4?(S.i===7?'修律馆':'正式审理堂'):'人物会面'}</div></section>`);Q=lines.slice();done=cb;nextLine()};
nextLine=function(){if(!Q.length){hide();const f=done;done=null;if(f)f();return}const l=Q.shift(),d=document.getElementById('vDialog');d.classList.remove('hidden');document.getElementById('vSpeaker').textContent=l[0];document.getElementById('vText').textContent=l[1];const cast=document.querySelector('.av-character-scene');if(cast){const mine=l[0]===C.role;cast.querySelector('.left')?.classList.toggle('dim',!mine);cast.querySelector('.right')?.classList.toggle('dim',mine)}const b=document.getElementById('vChoices');b.innerHTML='';document.getElementById('vNext').hidden=!!l[2];if(l[2])l[2].forEach((x,i)=>{const y=document.createElement('button');y.innerHTML=`<b>${String.fromCharCode(65+i)}</b>${x[0]}<small>${x[2]}</small>`;y.onclick=e=>{e.stopPropagation();S.choices.push(x[1]);save();nextLine()};b.appendChild(y)})};
/* 第二至第八卷脚本定稿：每卷独立人物、地图、证物边界与完整结局 */
const FINAL=[null,
 {scenes:['咸阳南门','县邑里门','县署案房','县廷决狱'],people:['木夫季','变法令史','里正','赵母','韩甲'],opening:[['木夫季','我不过把木头从南门搬到北门。众人都说官府不会真给重赏——县令，告示上的赏格还算数吗？'],['秦县令','新法第一次面对百姓，你如何兑现南门之赏？',[[`足额兑现，并把赏券和给付过程公开记入簿册`,'reward_full','政府先履行自己公布的承诺'],[`赏金太高，临时减半`,'reward_half','官府自行改变公开标准'],[`只给口头表彰，不给实赏`,'reward_words','法令承诺停留在文字上'],[`处罚围观者，以严刑显示新法威势`,'reward_fear','把信用误作单纯恐惧']]],['变法令史','赏已兑现，新法便应无所回避。赵武逃役归里，其母藏子，十户同伍，正当尽数连坐。'],['里正','两户当夜在外服驿役，根本不知赵武归来。若连不在场也同罚，百姓信的是法，还是官吏一句话？']],meet:[[['变法令史','什伍相保，一家藏奸，全伍有责。逐户核实知情，连坐之威便散了。'],['秦县令','威势能否代替事实？不在场者也应承担同样责任吗？'],['变法令史','新法求的是人人互察。责任若只落在藏匿者，旁人便会装作不知。']], [['里正','赵母确曾送饭藏子；但驿役册可证明两户不在里。韩甲的告书也夹着一桩争田旧怨。'],['秦县令','旧怨是否足以让整份告书失效？'],['里正','不能。真实线索要采用，借告奸诬陷的部分也要追究；否则奖励会变成私怨的刀。']]],evidence:[['南门赏券','券上写明木夫季徙木所得赏格，县府给付记录完整。','证明官府兑现承诺并建立初步信用。','不能证明以后任何严厉处罚都属于“守信”。'],['什伍名籍','十户被编为一伍，载有户主、亲属及互保关系。','证明身份编组和相互监督关系存在。','不能直接证明每户都知道赵武藏匿。'],['驿役记录','两户男子在案发前已奉命赴驿，归期晚于赵武被捕。','证明两户案发时不在里中。','不能反推其余住户必然知情。'],['韩甲告书','告发三户协助藏匿；田契显示韩甲与其中一户有争地旧怨。','提示告发动机复杂，必须逐项核验。','不能因此认定韩甲全部陈述都是虚假。']],boundary:'徙木立信、商鞅变法、什伍连坐和告奸属于法制史知识；赵武、赵母、韩甲及本县审理过程为教学化虚构。',stories:{good:'<h2>信与刑之间</h2><p>你足额兑现徙木赏格，又把十户分别询问。赵武依法受罚，赵母因积极藏匿承担责任；确实知情而不告者受罚，两户持驿役记录者获释。韩甲告书中的真实线索被采用，借争田旧怨捏造的部分则被追究。</p><h3>数月以后</h3><p>县中百姓仍畏惧新法，却渐渐相信公开的赏罚不会由官吏随意改变。里正说：“从前只怕官府，如今也会问官府是否照自己写下的规则办事。”连坐与告奸的严厉结构并未消失，但法令信用不再只来自恐惧。</p>',hard:'<h2>举里皆惧</h2><p>十户全部被罚，包括案发时远在驿站的住户。韩甲因告奸得赏，越来越多人学会用告书解决私怨。</p><h3>一年以后</h3><p>逃兵减少了，邻里也不再彼此信任。有人见邻人犯错，不再劝止，只等待换取赏赐的时机。县里看似安静，家家夜间却紧闭门户。</p>',weak:'<h2>法令失信</h2><p>你临时削减南门赏格，又在逃兵案中反复改变连坐标准。百姓发现告示写得再清楚，官府也能随时换一种说法。</p><p>有人不再相信告发会得赏，也有人相信行贿便可脱免。新法依旧严厉，却失去稳定；真正决定结果的，仍是官吏当日的态度。</p>'}},
 {scenes:['长安城门','廷尉狱署','刑制议堂','未央奏议'],people:['缇萦','廷尉正','淳于意','狱吏','河东使者'],opening:[['旁白','囚车穿过长安城门。淳于意将受肉刑，幼女缇萦一路追随，手中紧握写给天子的奏书。'],['缇萦','妾愿没入为官婢，以赎父刑。人受肉刑，身体残毁，即使愿意改过，也再没有恢复的机会。'],['廷尉府属官','你怎样接收这封奏书？',[[`把它作为对肉刑不可逆性的制度批评`,'petition_system','从个案进入刑罚目的'],[`只把它记作孝女救父`,'petition_filial','制度问题被缩成感人故事'],[`因女子议刑而拒收`,'petition_reject','身份阻断制度意见'],[`只求赦父，不讨论普遍规则`,'petition_pardon','个案恩赦不能代替改革']]],['廷尉正','肉刑沿用已久，见刑于身，足以禁奸。废之以后，凭什么使人畏惧？']],meet:[[['廷尉正','黥、劓、刖虽酷，却能使众人一望知戒。若改作笞刑，犯者岂不轻视国法？'],['廷尉府属官','刑罚目的只有威慑吗？永久伤残是否也堵死改过之路？'],['廷尉正','改革可以议，但若替刑无等差、执行无尺度，所谓仁政反会失去秩序。']], [['缇萦','我没有说父亲必然无罪。我说的是：一刀落下，改过也无法让鼻与足再生。'],['廷尉府属官','若废肉刑后，高额笞刑仍致人死伤呢？'],['缇萦','那就不应只庆祝刑名改变，还要把行刑后果写进奏报，让改革继续纠错。']]],evidence:[['缇萦奏书','奏书从父亲个案提出肉刑造成永久残毁、使人无由改过。','证明申诉包含普遍的刑罚制度批评。','不能证明淳于意在原案中必然无罪。'],['旧日行刑簿','簿中记有黥、劓、刖后长期伤残及无法复业者。','证明肉刑的伤害具有永久性。','不能仅凭刑罚残酷认定所有受刑者都是冤案。'],['替刑草案','草案拟以笞刑、徒刑代替肉刑，但部分罪名笞数极高，刑具与部位未定。','证明废刑方向尚未解决执行尺度。','不能因为名称较轻，就推定实际伤害必然较低。'],['河东伤亡奏报','新制试行后出现高额笞刑致死、致残记录。','证明替代刑的实际后果需要反馈和修正。','不能由局部伤亡直接否定废除肉刑的改革方向。']],boundary:'缇萦上书和汉文帝刑制改革具有史实基础；具体行刑簿、草案讨论和玩家参与方式为教学化设计。',stories:{good:'<h2>史官之笔</h2><p>肉刑被废，替代刑按罪责分等。你限制笞数、规定刑具与行刑部位，并要求各郡如实上报伤亡。淳于意获得重新审理，缇萦终于回到父亲身边。</p><h3>数年以后</h3><p>改革仍造成新的死伤，但数字没有被藏起来。朝廷据此继续调整笞刑。史官写道：“善法并非从不犯错，而是让错误被看见，并据此继续修正。”</p>',hard:'<h2>笞下新伤</h2><p>肉刑名称被废，所有罪行却统一改为高额笞刑。诏书宣称仁政已成，狱中却不断有人死于杖下。</p><p>他们没有被割鼻断足，也不再背负旧刑名，却仍未能活着走出刑场。形式改变了，实际伤害可能更加沉重。</p>',weak:'<h2>一人得赦</h2><p>你只帮助缇萦救下父亲，没有触动普遍制度。父女在长安城门相拥时，另一辆囚车正从他们身旁驶入。</p><p>车上犯人将承受同样的肉刑，却没有一个能够上书的女儿。恩赦改变了一家人的命运，规则依旧等待下一场偶然的仁慈。</p>'}},
 {scenes:['长安染坊','崔氏宅院','大理寺案库','大理寺法堂'],people:['崔安','崔六','库吏','邻人','大理寺博士'],opening:[['旁白','官帛在染坊失窃。崔六逃入兄长崔安家中，崔安拒绝告发，并称弟弟整夜在家；官差却在灶后发现被烧过的官帛碎片。'],['崔安','律许同居亲属相隐。我不亲手把弟弟送入官府，何罪之有？'],['大理寺评事','你先划定哪一道边界？',[[`区分不告发、虚假证明、藏赃、助逃和共同盗窃`,'kin_distinguish','亲隐必须对应具体行为'],[`兄弟同居便一门同罪`,'kin_same','身份替代行为调查'],[`亲属关系使一切协助免责`,'kin_absolute','有限容隐被扩成绝对屏障']]],['库吏','官帛出现在崔宅，兄弟又同居，还分什么行为？一并定罪最快。']],meet:[[['库吏','官帛是官物。崔六盗帛、崔安藏人藏物，兄弟同处一宅，何必再分？'],['大理寺评事','住宅发现碎片，只能证明什么？能否直接证明崔安参与最初盗窃？'],['库吏','不能直接证明，但若过度宽容亲隐，官物便会尽数藏进亲属家中。']], [['崔安','我是兄长，不告发弟弟是人伦。若连沉默也与盗窃同罪，亲属之义何在？'],['大理寺评事','沉默与编造不在场、焚毁官帛，是否仍是同一种行为？'],['崔安','我愿你依律分辨，但别因我姓崔、与他同居，就先把我写成盗犯。']]],evidence:[['染坊账簿','记载崔六案发时领取染料并进入官帛库旁工间。','证明崔六案发时曾在染坊活动。','不能单独证明他完成盗窃，更不能证明崔安参与。'],['崔安初供','初称崔六整夜在家，后又承认其深夜归宅，前后矛盾。','削弱崔六不在场说法，并提示虚假陈述。','不能仅凭供述矛盾认定兄弟共同盗窃。'],['官帛碎片','带官府织记的帛片在崔宅灶后发现，有焚烧痕迹。','支持赃物曾被带入住宅并可能遭隐藏、毁弃。','不能自动证明崔安知道来源或参与原盗。'],['邻里证言','邻人称深夜看见兄弟二人在灶前焚烧织物。','可与碎片和初供互证积极处理赃物。','不能排除夜色误认，也不能单独证明崔安参与盗取。']],boundary:'《唐律疏议》及亲属容隐属于历史制度；崔氏兄弟、官帛案和证据组合为教学化虚构。',stories:{good:'<h2>礼法有界</h2><p>你承认崔安不主动告发弟弟受亲属伦理保护，却分别审查虚假证明和藏匿官帛。崔六对盗帛负责；崔安不因兄长身份自动同罪，但因积极隐藏、毁弃赃物承担相应责任。</p><p>崔安问：“既允许相隐，为何我仍受罚？”你答：“容许你不亲手送弟入官，不等于允许你改变事实、毁灭证据。”礼被承认，却没有吞没行为责任。</p>',hard:'<h2>一门同罪</h2><p>你以兄弟同居为由将二人同罪。案件迅速结清，官帛也获追偿。此后，只要家中一人涉案，整户便先隐藏关系、逃离住所。</p><p>身份取代行为调查，办案更快，也更粗糙。</p>',weak:'<h2>亲隐无边</h2><p>你认为亲属关系可使全部协助免责。拒绝告发、编造证词、转移官帛和助逃都被装进“亲隐”二字。</p><p>越来越多盗犯把赃物送进亲属宅院。亲属伦理从有限容隐，变成逃避责任的绝对屏障。</p>'}},
 {scenes:['临安药圃','县衙验所','提刑司案房','别勘法堂'],people:['陆惟恭','原审知县','仵作','药圃管事','雨夜证人'],opening:[['旁白','赵员外死于雨夜药圃。赘婿陆惟恭在夹讯后认罪，又在押解途中翻供。县衙说短刀是凶器，尸格却只记颈部索沟。'],['陆惟恭','刀上无血，尸身无刀伤。我的口供是在刑具下照着县役的话说的。'],['提刑司属官','面对翻供，你先做什么？',[[`核对尸格、凶器、雨势和刑讯记录，决定是否别勘`,'review_chain','以外部证据检验口供'],[`有认罪便维持原审`,'keep_confession','口供压过客观矛盾'],[`翻供即视为当然无罪`,'auto_acquit','翻供也需要调查'],[`只找一名新证人替代口供`,'single_witness','从一个单证据跳到另一个']]],['原审知县','案犯已经画押。若每次翻供都重开案卷，县衙还如何结案？']],meet:[[['原审知县','陆惟恭先供投毒，再说持刀。供词虽有细节出入，终究已经认罪。'],['提刑司属官','尸格没有刀伤，短刀没有血迹。为何应让口供压过这些矛盾？'],['原审知县','刑讯是为得实。若凡受讯之供都疑，狱案将无从定夺。']], [['仵作','尸格写的是颈部索沟，不是刃伤。短刀像园中工具，雨夜证言也未必看得清脸。'],['提刑司属官','尸伤是否就能独自说出凶手？'],['仵作','不能。口供会看刑具脸色，尸伤不会；可尸伤仍要由人正确读取，并与现场、天气和证言互证。']]],evidence:[['尸格','死者颈部有连续索沟，没有刺切创口。','支持死因更接近绳索勒颈，并反驳短刀致命叙事。','不能单独确认凶手身份。'],['无血短刀','刀为药圃常用工具，刃上没有可见血迹。','削弱其作为直接致命凶器的可能。','不能证明刀从未被持拿，也不能仅凭无血排除所有用途。'],['雨势簿','目击者所称时辰正值暴雨，能见度极低。','削弱远距离辨认面容的可靠性。','不能证明目击者必然撒谎或现场无人经过。'],['刑讯记录','陆惟恭认罪发生在夹讯后，供述细节随问话多次改变。','提示口供可能迎合预设案情。','不能仅因受刑讯便当然认定被告无罪。']],boundary:'《洗冤集录》、尸格、检验和翻异别勘体现宋代司法知识；药圃案件及人物为教学化虚构。',stories:{good:'<h2>雨歇见痕</h2><p>你启动别勘，重新检验尸伤和现场。赵员外死于绳索勒颈，短刀只是园中工具；雨夜证人看到的“陆惟恭”，只是穿着相似蓑衣的人。</p><p>药材账目最终指向侵吞公款的管事。陆惟恭获释时问：“若没有尸格上的索沟，我的供词是否就会成为全部真相？”仵作答：“尸伤也要由人读懂，所以才要让证据彼此说话。”</p>',hard:'<h2>供词成狱</h2><p>你维持原审，陆惟恭被定罪。数年后，管事在另一案中供出雨夜旧案。</p><p>原卷重开时，短刀依然无血，尸格上的索沟也从未消失。错误不是没有留下痕迹，只是当时无人允许痕迹挑战口供。</p>',weak:'<h2>一言定罪</h2><p>你推翻口供，却完全依赖一名目击者改判他人。后来查明，证人在暴雨中根本无法看清面容。</p><p>案件从“唯口供”转为“唯一目击证言”，一个单一证据被推翻，另一个又占据全部真相。</p>'}},
 {scenes:['江南沈宅','县衙户房','官印库房','县堂听讼'],people:['沈素娘','沈族叔','陆家中人','赵家中人','户房书吏'],opening:[['旁白','沈素娘的族叔先后收取陆、赵两家聘财，两家今日同时持婚书到县衙。陆家文书上还有知县朱批，印文却与官样略有不同。'],['沈素娘','两份婚书都写着我的名字，却没有一句是我说的话。族叔还占着父亲留下的田产。'],['江南县丞','你怎样进入这宗婚案？',[[`分别核验主婚权限、两份婚书、聘财和官批真伪`,'marriage_layers','在明代制度内拆分问题'],[`聘财多者当然得婚`,'highest_bid','把婚姻完全当作财物交易'],[`直接宣布适用现代婚姻自由`,'modern_only','价值清楚却跳过历史规范'],[`交回宗族，不问伪造官批`,'clan_return','家族权力覆盖官府文书问题']]],['沈族叔','孤女婚事本应由族中长者作主。我为宗族筹措用度，收两家聘财又有何妨？']],meet:[[['沈族叔','父母既亡，族中长辈自然主婚。陆赵两家皆是良配，择聘财丰厚者有何不可？'],['江南县丞','你是否具有主婚权限？两次收聘、占用家产又如何解释？'],['沈族叔','那是宗族内部之事，县衙不应把家礼拆成几宗罪责。']], [['沈素娘','我知道当时不是人人都能自己定婚，但族叔不是父母，也不能拿同一桩婚事收两次钱。'],['江南县丞','你希望哪些话进入正卷？'],['沈素娘','写清我从未参与订约、官批并非我所求，也写清族叔一直控制我的田产。别让案卷只剩两张婚书。']]],evidence:[['两家婚书','陆、赵两份婚书日期相近，主婚人均署沈族叔。','证明存在重复订约及主婚人身份。','不能仅凭文书外观判断两约效力或官批真伪。'],['两家聘财簿','族叔先后收受两家银、绢及礼物，部分已用于个人债务。','证明重复收聘及财物流向。','不能单独决定婚约归属。'],['县印样式簿','陆家婚书朱批印文的篆画、缺口与同期县印不符。','支持官批可能伪造，应另案追查。','不能仅凭一处差异直接锁定具体伪造者。'],['沈素娘陈词','陈述未参与两次订约、父母已亡、族叔控制家产。','支持审查主婚权限与财产关系，并使本人处境进入案卷。','不能直接以现代婚姻自主原则替代全部明代户婚规则。']],boundary:'明代户婚、父母主婚、婚书聘财和官文书规则属于历史制度；沈素娘案为教学化虚构。',stories:{good:'<h2>婚书之外</h2><p>你核验婚书、聘财和主婚权限，认定族叔无权私自处分婚事，却先后收取两家财物；陆家朱批由中间人伪造。</p><p>判词分别处理婚约效力、重复收聘、财物返还、伪造官文书和族叔侵占家产。素娘没有立刻获得现代意义上的完全婚姻自主，但她的陈述第一次完整进入正卷，不再只是两份婚书上的同一个名字。</p>',hard:'<h2>宗祠定婚</h2><p>你把案件交回宗族。族长决定素娘嫁给聘财较高的一方，伪造朱批不再追究。</p><p>几年后，族叔又以家族名义处分另一名孤女的婚姻和财产。官府维护了宗族秩序，也把文书伪造与重复收聘留在宗祠门外。</p>',weak:'<h2>越代判词</h2><p>你直接宣布婚姻必须完全由本人自由决定，却没有处理聘财、伪造朱批和族叔权限。</p><p>素娘暂时获救，两家仍为财物争执，伪造者也未担责。判词符合现代价值，却无法说明它在明代案卷中如何适用。</p>'}},
 {scenes:['刑部秋审处','原审卷库','仵作复核房','秋审大堂'],people:['周成','周母','原审知县','秋审司官','关键证人'],opening:[['旁白','周成因械斗致死被判斩监候，原审拟列“情实”。秋审前，证人翻供，供词上有刑讯记号，尸伤方向又与所报凶器不符。'],['周母','他是独子。我求的不是因他要养我便说他无罪，只求先把事实查清，再谈他该不该留下。'],['秋审司官','你先审查哪一层？',[[`先核事实疑点，再分别考虑情节和留养`,'facts_first','事实、宽宥、家庭身份分层'],[`维护原审威信，直接列情实`,'confirm_real','既判压过不可逆风险'],[`独子身份足以直接留养`,'family_first','家庭身份覆盖事实判断'],[`把事实不清直接写成可矜`,'mix_categories','混淆证明与宽宥']]],['原审知县','案已定谳。若因一纸翻供便重开旧卷，地方官的威信何在？']],meet:[[['原审知县','周成已经认罪，凶器也已报部。秋审本为定类，不该替地方重做一遍审问。'],['秋审司官','供词为何有夹讯记号？致命伤方向为何与凶器相反？'],['原审知县','卷宗若处处可疑，天下死案何时才能执行？']], [['周母','我知道他参加了械斗，也不敢说他全无责任。可证人已经改口，伤痕也对不上。'],['秋审司官','若事实核清后仍有罪，你是否只主张留养？'],['周母','是。事实是事实，奉养是奉养。不能因他是独子就说无罪，也不能因他有老母就不看疑点。']]],evidence:[['刑讯供词','认罪供述形成于夹讯后，数处关键细节与问词顺序一致。','提示供词可能受刑讯和诱导影响。','不能因此当然认定周成未参与械斗。'],['仵作格目','致命创自右后方向斜入，与原报周成正面持刀的说法不合。','证明尸伤与指控方式存在重要矛盾。','不能单独确认真正实施致命伤者。'],['证人翻供书','关键证人称原供受到县役诱导，并请求重新对质。','使原证言可靠性受到动摇，应核查翻供原因。','不能把翻供自动等同真实陈述。'],['周氏户籍与奉养材料','周成为独子，母年老无其他成年奉养人。','支持进入留养承祀的身份与家庭审查。','不能回答杀人事实，也不能代替对致命伤的核验。']],boundary:'斩监候、秋审分类、可矜和留养承祀属于清代制度；周成案及证据组合为教学化虚构。',stories:{good:'<h2>红册缓勾</h2><p>你先审事实，再考虑家庭情节。案件列入缓决，证人重新对质，尸伤重新核验。调查显示周成参加械斗，但致命伤可能来自另一人。</p><p>周成没有立即获释，死刑也未当然取消，执行被暂缓。周母离开刑部时说：“我求的不是因他是独子便无罪，只求事实清楚以后，再谈他该不该留下。”秋审既体现皇权终裁，也成为纠正原审的第二道门。</p>',hard:'<h2>情实勾决</h2><p>你为维护既判与官府威信，维持情实。刑讯记号、尸伤矛盾和翻供没有进入最终题本。</p><p>数年后，另一名械斗者临死前承认自己造成致命伤。红册文字已经褪色，死刑却无法撤回。</p>',weak:'<h2>留养之门</h2><p>你直接因独子身份主张留养，没有审查事实疑点。周成得到暂缓，母亲获得奉养。</p><p>另一名案情和家庭情况相似的犯人，因无人代为陈情仍被列为情实。宗法孝养进入死刑审查，也可能使相同案件因家庭身份得到不同结果。</p>'}},
 {scenes:['修订法律馆','礼法会议厅','各省司法档案室','新刑律表决厅'],people:['沈家本','礼教派大臣','外务官','外国顾问','报馆记者'],opening:[['旁白','清末修订法律馆。新刑律草案试图区分犯罪与道德、减少比附；礼教派担心亲属名分动摇，外务官又希望借修律收回领事裁判权。'],['沈家本','刑律应限定国家刑罚权。若一切不合伦理之事都入刑，刑法便没有尽头。'],['修订法律馆参议','你以何种原则审读草案？',[[`逐条区分犯罪、伦理评价与过渡规范，并公开理由`,'modern_transition','把边界写进制度'],[`传统伦理全部原样入刑`,'all_ritual','法典更名而结构不变'],[`完全照搬外国法典`,'copy_foreign','技术文本脱离实施条件'],[`只为换取列强承认而修律`,'foreign_exchange','把主权误作法典交易']]],['礼教派大臣','中国以亲属名分立国。新律若只论抽象个人，不论尊卑亲疏，这又是谁的法律？']],meet:[[['礼教派大臣','伦理并非私德。亲属名分维系家国秩序，刑律若尽数删除相关规范，社会凭什么维持？'],['修订法律馆参议','哪些行为具有严重社会危害，哪些主要属于伦理评价？可否逐条说明，而不是把所有争议一次入刑？'],['礼教派大臣','我反对的不是文字整齐，而是移植时把本国社会关系一并抹去。']], [['沈家本','近代刑法体例可以限制比附、明确罪刑，但外国条文不能逐字落地。各省法院、监狱和人才尚未齐备。'],['修订法律馆参议','修律能否直接换回领事裁判权？'],['沈家本','修律是收回司法主权的重要条件之一，不是自动交换。文本、机构、人才和实际审判能力必须一同改变。']]],evidence:[['新刑律草案','采用近代专门刑法典体例，重构犯罪、主刑从刑并减少比附。','证明法典技术和刑罚体系正在转型。','不能证明新制度已经具备全面实施条件。'],['礼教派签注','逐条反对删除部分亲属伦理规范，并提出社会秩序理由。','证明礼法之争涉及法律与伦理边界。','不能把所有意见简单视为无知守旧，也不能证明传统规范都应入刑。'],['领事裁判照会','列强以司法制度为由拒绝立即放弃领事裁判权。','证明修律与国家司法主权目标相关。','不能证明照搬外国法典即可自动收回主权。'],['各省司法报告','多省报告审判机构、监狱条件和新法人才不足。','证明法典改革必须考虑实施能力与过渡安排。','不能因此认定近代法典改革毫无必要。']],boundary:'《大清新刑律》、礼法之争与领事裁判权问题有史实依据；会议对话、具体签注组合和玩家表决为教学化设计。',stories:{good:'<h2>新律未竟</h2><p>你采用近代刑法体例，明确犯罪与刑罚边界；对部分伦理争议设置过渡规范，并公开修改理由。</p><p>新律在争论和妥协中完成，却未及在清朝充分实施，王朝便走向终结。修订馆关闭前，老参议抚着草案说：“我们没有完成一个时代，却改变了后人讨论刑法时使用的语言。”它没有立即解决治外法权和司法能力，却影响了此后的刑法道路。</p>',hard:'<h2>旧律新名</h2><p>你保留旧律主要伦理和身份结构，只改变名称与部分刑罚。反对声音暂时减少，新法却仍大量依赖旧有比附和身份规范。</p><p>外国使节认为中国只是换了法典外观。法典有了新名字，制度仍生活在旧秩序中。</p>',weak:'<h2>纸上主权</h2><p>你完全照搬外国法典，希望迅速获得列强承认。外国顾问称赞技术先进，各省官员却不知如何适用，监狱、审判机关和人才也未同步改革。</p><p>领事裁判权没有立即撤废。你终于明白：法律近代化与国家主权相连，却不能用一部翻译法典直接交换主权。</p>'}}
];
FINAL.slice(1).forEach((d,i)=>{const c=V[i+1];Object.assign(c,d);c.evidence=d.evidence;c.stories=d.stories});
