 era:'战国·秦孝公变法初期',role:'杜县新任县令',theme:'徙木立信、什伍连坐、告奸与诬告',
 scenes:['栎阳南门','杜县赵宅','杜县县署案房','杜县里门法堂'],people:['季良','卫成','田伯','孟媪','韩甲'],
 opening:[
  ['旁白','新法颁布前，栎阳南门立起三丈高木。告示悬赏搬至北门者，百姓却怀疑这是官府设下的陷阱。'],
  ['季良','我已把木头搬到北门。告示写的是重赏，官府真的不会反悔吗？'],
  ['杜县新任县令','赏金发放前，你提出什么意见？',[[`足额兑现，并把赏券、给付和见证者公开记入簿册`,'reward_full','赏罚必信首先约束政府承诺'],[`赏格过高，临时减半`,'reward_half','公开标准被官府自行改变'],[`只给荣誉，不给实赏`,'reward_words','徙木失去兑现承诺的意义'],[`以贪利、扰乱城门为由处罚季良`,'reward_trap','告示被理解为官府陷阱']]],
  ['卫成','赏既写明，便不可少一金；刑既公布，也不可因人增减。三日后，新法将随驿骑送到杜县。'],
  ['旁白','黄昏，孟媪跪在杜县衙门前，承认藏匿逃兵之子赵武。韩甲几乎同时递上告书，声称田伯、孙乙、陈家乃至整伍都曾相助。'],
  ['卫成','新法入县第一案，若不迅速全伍收押，人人都会说自己不知。连坐还有什么威势？'],
  ['杜县新任县令','你怎样处置十户？',[[`暂记全伍，夜搜赵宅后分别调查知情、藏匿和不在场`,'detain_investigate','执行新法同时核查责任基础'],[`立即将全伍十户收押`,'detain_all','威慑迅速但身份替代事实'],[`只追究赵武，不调查任何他人`,'only_deserter','忽略当时匿奸与互监结构']]],
  ['孟媪','是我给了他饭，把他藏在柴房。孙乙只知道有人受寒，陈家当夜根本不在杜县。罪在老妇，不能让未见过他的人同罚。']
 ],
 meet:[
  [['卫成','什伍相保，一家藏奸，全伍有责。若逐户核实知情，连坐之威便散了。'],['杜县新任县令','严格执行是否等于不调查事实？人在河西服役，也要当作当夜协助吗？'],['卫成','新法初行，迟疑会被看成软弱。但若官府允许虚假告书换赏，新法同样会失去信用。'],['卫成','你若坚持调查，就必须给出一套能稳定执行、而非临时开恩的标准。']],
  [['田伯','孙乙承认送过冬衣，却说不知道给谁；陈家兄弟有河西驿役记录。韩甲与陈家争田，还曾威胁等新法下来便让他们离开。'],['杜县新任县令','韩甲确实帮助找到赵武，这是否使他其余陈述都可信？'],['田伯','不。真实部分可以采用，虚构部分也要追究。否则百姓学会的不是告奸，而是借法害人。'],['孟媪','我不求亲情使我无罪，只求别把我的知情写到所有邻人的名下。']]
 ],
 evidence:[
  ['南门赏券','季良已依告示取得全额赏金，给付过程有官吏记录和百姓见证。','官府通过兑现公开奖赏建立了新法的初步信用。','不能证明对所有嫌疑人施以重罚都是守信，也不能证明连坐越广信用越高。'],
  ['什伍名籍','赵、韩、孙、陈等十户同编一伍；田伯负责登记，赵韩及韩陈之间均有田界争议记录。','证明各户处于同一基层互监关系，也提示部分告发存在利益冲突。','不能直接证明每户都知情、共同藏匿或掌握相同信息。'],
  ['驿役和徭役记录','陈家兄弟在赵武返乡前十日已赴河西服役，驿站出入记录显示案发后方归。','证明陈家关键时段不在杜县，并与“当夜助逃”的告发冲突。','不能证明陈家此前从未与赵武联系，也不能证明韩甲其他告发全假。'],
  ['韩甲告书与田契','告书称赵、孙、陈三家共同藏匿；田契显示韩甲与陈家争夺水渠旁土地，并曾扬言借新法逼迁。','证明韩甲可能具有报复动机，对陈家指认必须逐项核验。','不能因存在旧怨就排除全部陈述，也不能否认赵武确曾藏在赵宅。']
 ],
